import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] nums = ints(data, "nums");
        int k = num(data, "k");
        double total = 0;
        for (int i = 0; i < k; i++) total += nums[i];
        double best = total;
        for (int right = k; right < nums.length; right++) {
            int left = right - k + 1;
            total += nums[right] - nums[right - k];
            best = Math.max(best, total);
            trace(
                "nums",
                nums,
                "left",
                left,
                "right",
                right,
                "total",
                total,
                "best",
                best
            );
        }
        return best / k;
    }
}

