public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s");
        int k = num(data, "k"),
            left = 0,
            most = 0,
            best = 0;
        Map<Character, Integer> counts = new HashMap<>();
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            counts.put(c, counts.getOrDefault(c, 0) + 1);
            most = Math.max(most, counts.get(c));
            while (right - left + 1 - most > k) {
                char old = s.charAt(left++);
                counts.put(old, counts.get(old) - 1);
            }
            best = Math.max(best, right - left + 1);
            trace("s", s, "left", left, "right", right, "best", best, "counts", counts);
        }
        return best;
    }
}

minimum-window:
import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s"),
            t = str(data, "t");
        if (t.isEmpty()) return "";
        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) need.put(c, need.getOrDefault(c, 0) + 1);
        int left = 0,
            missing = t.length(),
            start = 0,
            best = Integer.MAX_VALUE;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (need.getOrDefault(c, 0) > 0) missing--;
            need.put(c, need.getOrDefault(c, 0) - 1);
            while (missing == 0) {
                if (right - left + 1 < best) {
                    best = right - left + 1;
                    start = left;
                }
                char old = s.charAt(left++);
                need.put(old, need.get(old) + 1);
                if (need.get(old) > 0) missing++;
            }
            trace("s", s, "left", left, "right", right, "missing", missing, "best", best);
        }
        return best == Integer.MAX_VALUE ? "" : s.substring(start, start + best);
    }
}

