        int[] nums = ints(data, "nums");
        int target = num(data, "target"),
            left = 0,
            right = nums.length - 1;
        while (left < right) {
            long total = (long) nums[left] + nums[right];
            trace("nums", nums, "left", left, "right", right, "total", total);
            if (total == target) return new int[] { left + 1, right + 1 };
            if (total < target) left++;
            else right--;
        }
        return new int[0];
    }
}

