// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] nums = ints(data, "nums");
        Arrays.sort(nums);
        List<int[]> result = new ArrayList<>();
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int left = i + 1,
                right = nums.length - 1;
            while (left < right) {
                long total = (long) nums[i] + nums[left] + nums[right];
                trace(
                    "nums",
                    nums,
                    "i",
                    i,
                    "left",
                    left,
                    "right",
                    right,
                    "total",
                    total,
                    "result",
                    result
                );
                if (total < 0) left++;
                else if (total > 0) right--;
                else {
                    result.add(new int[] { nums[i], nums[left], nums[right] });
                    int a = nums[left],
                        b = nums[right];
                    while (left < right && nums[left] == a) left++;
                    while (left < right && nums[right] == b) right--;
                }
            }
        }
        return result;
    }
}

