// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] nodes = ints(data, "values"),
            links = makeLinks(nodes.length, -1);
        int slow = nodes.length > 0 ? 0 : -1,
            fast = slow;
        while (fast != -1 && links[fast] != -1) {
            slow = links[slow];
            fast = links[links[fast]];
            trace("nodes", nodes, "links", links, "slow", slow, "fast", fast);
        }
        return walk(nodes, links, slow);
    }

    // Index-based links make pointer changes visible.
    static int[] makeLinks(int n, int pos) {
        int[] links = new int[n];
        for (int i = 0; i < n; i++) links[i] = i + 1 < n ? i + 1 : pos;
        return links;
    }

    static List<Integer> walk(int[] nodes, int[] links, int head) {
        List<Integer> result = new ArrayList<>();
        Set<Integer> seen = new HashSet<>();
        while (head != -1 && seen.add(head)) {
            result.add(nodes[head]);
            head = links[head];
        }
        return result;
    }
}

