public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] nums = ints(data, "nums2");
        Deque<Integer> stack = new ArrayDeque<>();
        Map<Integer, Integer> next = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            while (!stack.isEmpty() && stack.peekLast() < nums[i])
                next.put(stack.removeLast(), nums[i]);
            stack.addLast(nums[i]);
            trace("nums", nums, "stack", stack, "i", i, "next", next);
        }
        return Arrays.stream(ints(data, "nums1"))
            .map(v -> next.getOrDefault(v, -1))
            .toArray();
    }
}

