import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] position = ints(data, "position"),
            speed = ints(data, "speed");
        int target = num(data, "target");
        Integer[] order = new Integer[position.length];
        for (int i = 0; i < order.length; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> Integer.compare(position[b], position[a]));
        List<Double> stack = new ArrayList<>();
        for (int i : order) {
            double arrival = (double) (target - position[i]) / speed[i];
            if (stack.isEmpty() || arrival > stack.get(stack.size() - 1)) stack.add(
                arrival
            );
            trace("position", position[i], "arrival", arrival, "stack", stack);
        }
        return stack.size();
    }
}

