        String s = str(data, "s");
        Deque<Character> stack = new ArrayDeque<>();
        String open = "([{",
            close = ")]}";
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            int j = close.indexOf(c);
            if (j >= 0) {
                if (stack.isEmpty() || stack.removeLast() != open.charAt(j)) return false;
            } else stack.addLast(c);
            trace("s", s, "stack", stack, "i", i);
        }
        return stack.isEmpty();
    }
}

