import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        Deque<Long> stack = new ArrayDeque<>();
        for (String token : strings(data, "tokens")) {
            if (token.length() == 1 && "+-*/".contains(token)) {
                long b = stack.removeLast(),
                    a = stack.removeLast();
                stack.addLast(
                    token.equals("+")
                        ? a + b
                        : token.equals("-")
                          ? a - b
                          : token.equals("*")
                            ? a * b
                            : a / b
                );
            } else stack.addLast(Long.parseLong(token));
            trace("stack", stack, "token", token);
        }
        return stack.peekLast();
    }
}

min-stack:
import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        Deque<Integer> stack = new ArrayDeque<>(),
            minima = new ArrayDeque<>();
        List<Object> result = new ArrayList<>();
        for (Object value : list(data.get("operations"))) {
            List<Object> op = list(value);
            String name = (String) op.get(0);
            if (name.equals("push")) {
                int n = integer(op.get(1));
                stack.addLast(n);
                minima.addLast(
                    Math.min(n, minima.isEmpty() ? Integer.MAX_VALUE : minima.peekLast())
                );
                result.add(null);
            } else {
                if (stack.isEmpty()) throw new IllegalArgumentException("Empty stack");
                if (name.equals("pop")) {
                    stack.removeLast();
                    minima.removeLast();
                    result.add(null);
                } else result.add(
                    name.equals("top") ? stack.peekLast() : minima.peekLast()
                );
            }
            trace("stack", stack, "minima", minima, "result", result);
        }
        return result;
    }
}

