import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s") + "+";
        Deque<Long> stack = new ArrayDeque<>();
        long value = 0;
        char operation = '+';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) value = value * 10 + c - '0';
            else if (c != ' ') {
                if (operation == '+') stack.addLast(value);
                else if (operation == '-') stack.addLast(-value);
                else if (operation == '*') stack.addLast(stack.removeLast() * value);
                else stack.addLast(stack.removeLast() / value);
                operation = c;
                value = 0;
                trace("s", s, "stack", stack, "i", i);
            }
        }
        long total = 0;
        for (long n : stack) total += n;
        return total;
    }
}

