import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] nodes = ints(data, "values"),
            links = makeLinks(nodes.length, -1);
        if (nodes.length == 0) return new int[0];
        int slow = 0,
            fast = 0;
        while (links[fast] != -1 && links[links[fast]] != -1) {
            slow = links[slow];
            fast = links[links[fast]];
        }
        int current = links[slow],
            previous = -1;
        links[slow] = -1;
        while (current != -1) {
            int following = links[current];
            links[current] = previous;
            previous = current;
            current = following;
            trace(
                "nodes",
                nodes,
                "links",
                links,
                "current",
                current,
                "previous",
                previous
            );
        }
        int first = 0,
            second = previous;
        while (second != -1) {
            int a = links[first],
                b = links[second];
            links[first] = second;
            links[second] = a;
            trace("nodes", nodes, "links", links, "current", first);
            first = a;
            second = b;
        }
        return walk(nodes, links, 0);
    }

    // Index-based links make pointer changes visible.
    static int[] makeLinks(int n, int pos) {
        int[] links = new int[n];
        for (int i = 0; i < n; i++) links[i] = i + 1 < n ? i + 1 : pos;
        return links;
    }

