import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] nodes = ints(data, "values"),
            links = makeLinks(nodes.length, -1);
        int k = num(data, "k"),
            head = nodes.length > 0 ? 0 : -1,
            tail = -1,
            current = head;
        while (current != -1) {
            int end = current;
            for (int i = 1; i < k && end != -1; i++) end = links[end];
            if (end == -1) break;
            int following = links[end],
                start = current,
                previous = following;
            while (current != following) {
                int next = links[current];
                links[current] = previous;
                previous = current;
                current = next;
                trace(
                    "nodes",
                    nodes,
                    "links",
                    links,
                    "current",
                    current,
                    "previous",
                    previous
                );
            }
            if (tail == -1) head = end;
            else links[tail] = end;
            tail = start;
            trace("nodes", nodes, "links", links, "head", head, "tail", tail);
        }
        return walk(nodes, links, head);
    }

    // Index-based links make pointer changes visible.
    static int[] makeLinks(int n, int pos) {
        int[] links = new int[n];
        for (int i = 0; i < n; i++) links[i] = i + 1 < n ? i + 1 : pos;
        return links;
    }

    static List<Integer> walk(int[] nodes, int[] links, int head) {
        List<Integer> result = new ArrayList<>();
        Set<Integer> seen = new HashSet<>();
        while (head != -1 && seen.add(head)) {
            result.add(nodes[head]);
            head = links[head];
        }
        return result;
    }
}

