import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] a = ints(data, "nums1"),
            b = ints(data, "nums2");
        if (a.length > b.length) {
            int[] swap = a;
            a = b;
            b = swap;
        }
        int left = 0,
            right = a.length,
            half = (a.length + b.length + 1) / 2;
        while (left <= right) {
            int i = (left + right) / 2,
                j = half - i;
            double al = i > 0 ? a[i - 1] : Double.NEGATIVE_INFINITY,
                ar = i < a.length ? a[i] : Double.POSITIVE_INFINITY,
                bl = j > 0 ? b[j - 1] : Double.NEGATIVE_INFINITY,
                br = j < b.length ? b[j] : Double.POSITIVE_INFINITY;
            trace("a", a, "b", b, "i", i, "j", j);
            if (al <= br && bl <= ar) return (a.length + b.length) % 2 == 1
                ? Math.max(al, bl)
                : (Math.max(al, bl) + Math.min(ar, br)) / 2;
            if (al > br) right = i - 1;
            else left = i + 1;
        }
        throw new IllegalArgumentException("Inputs must be sorted");
    }
}

