public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        Tree tree = new Tree(list(data.get("tree")));
        Deque<Integer> queue = new ArrayDeque<>();
        if (!tree.nodes.isEmpty()) queue.add(0);
        List<List<Integer>> result = new ArrayList<>();
        while (!queue.isEmpty()) {
            List<Integer> level = new ArrayList<>();
            int count = queue.size();
            while (count-- > 0) {
                int current = queue.remove();
                level.add(tree.nodes.get(current));
                for (int child : new int[] {
                    tree.left.get(current),
                    tree.right.get(current),
                })
                    if (child != -1) queue.add(child);
                tree.checkpoint(current, "queue", queue);
            }
            result.add(level);
        }
        return result;
    }

    static class Tree {

        List<Integer> nodes = new ArrayList<>(),
            left = new ArrayList<>(),
            right = new ArrayList<>();

        Tree(List<Object> values) {
            if (values.isEmpty() || values.get(0) == null) return;
            add(integer(values.get(0)));
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(0);
            int index = 1;
            while (!queue.isEmpty() && index < values.size()) {
                int parent = queue.remove();
                for (List<Integer> children : Arrays.asList(left, right)) {
                    if (index >= values.size()) break;
                    Object value = values.get(index++);
                    if (value != null) {
                        children.set(parent, nodes.size());
                        queue.add(nodes.size());
                        add(integer(value));
                    }
                }
            }
        }

        void add(int value) {
            nodes.add(value);
            left.add(-1);
            right.add(-1);
        }

        void checkpoint(int current, String key, Object value) {
            trace(
                "nodes",
                nodes,
                "left_child",
