import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        Trie trie = new Trie();
        List<Object> result = new ArrayList<>();
        for (Object op : list(data.get("operations"))) {
            List<Object> entry = list(op);
            String name = (String) entry.get(0),
                word = (String) entry.get(1);
            if (name.equals("insert")) {
                trie.add(word);
                result.add(null);
            } else {
                Trie node = trie;
                for (char c : word.toCharArray()) {
                    node = node.children.get(c);
                    if (node == null) break;
                }
                result.add(node != null && (name.equals("startsWith") || node.word));
            }
            trace("trie", trie.view(), "word", word, "result", result);
        }
        return result;
    }

    static class Trie {

        Map<Character, Trie> children = new TreeMap<>();
        boolean word;

        void add(String s) {
            Trie node = this;
            for (char c : s.toCharArray())
                node = node.children.computeIfAbsent(c, k -> new Trie());
            node.word = true;
        }

