public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        List<Object> board = list(data.get("board"));
        char[][] grid = new char[board.size()][];
        for (int r = 0; r < grid.length; r++) {
            List<Object> row = list(board.get(r));
            grid[r] = new char[row.size()];
            for (int c = 0; c < row.size(); c++) grid[r][c] = row
                .get(c)
                .toString()
                .charAt(0);
        }
        Trie trie = new Trie();
        for (String word : strings(data, "words")) trie.add(word);
        Set<String> found = new TreeSet<>();
        class Search {

            void visit(int row, int col, Trie node, String prefix) {
                if (
                    row < 0 || row >= grid.length || col < 0 || col >= grid[row].length
                ) return;
                char c = grid[row][col];
                Trie next = node.children.get(c);
                if (next == null) return;
                String word = prefix + c;
                if (next.word) found.add(word);
                grid[row][col] = '#';
                trace("grid", grid, "row", row, "col", col, "found", found);
                visit(row + 1, col, next, word);
                visit(row - 1, col, next, word);
                visit(row, col + 1, next, word);
                visit(row, col - 1, next, word);
                grid[row][col] = c;
            }
        }
        Search search = new Search();
        for (int r = 0; r < grid.length; r++) for (
            int c = 0;
            c < grid[r].length;
            c++
        ) search.visit(r, c, trie, "");
        return found;
    }

    static class Trie {

        Map<Character, Trie> children = new TreeMap<>();
        boolean word;

        void add(String s) {
