import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String begin = str(data, "beginWord"),
            end = str(data, "endWord");
        Set<String> words = new TreeSet<>(Arrays.asList(strings(data, "wordList")));
        if (!words.contains(end)) return 0;
        Deque<String> queue = new ArrayDeque<>();
        Map<String, Integer> distance = new HashMap<>();
        queue.add(begin);
        distance.put(begin, 1);
        List<String[]> edges = new ArrayList<>();
        while (!queue.isEmpty()) {
            String current = queue.remove();
            trace(
                "edges",
                edges,
                "current",
                current,
                "queue",
                queue,
                "visited",
                distance.keySet()
            );
            if (current.equals(end)) return distance.get(current);
            for (String word : words) {
                if (
                    word.length() != current.length() || distance.containsKey(word)
                ) continue;
                int diff = 0;
                for (int i = 0; i < word.length(); i++) if (
                    word.charAt(i) != current.charAt(i)
                ) diff++;
                if (diff == 1) {
                    distance.put(word, distance.get(current) + 1);
                    edges.add(new String[] { current, word });
                    queue.add(word);
                }
            }
        }
        return 0;
    }
}

