    static int flood(int[][] grid, int row, int col) {
        if (
            row < 0 ||
            row >= grid.length ||
            col < 0 ||
            col >= grid[row].length ||
            grid[row][col] != 1
        ) return 0;
        grid[row][col] = 0;
        trace("grid", grid, "row", row, "col", col);
        return (
            1 +
            flood(grid, row + 1, col) +
            flood(grid, row - 1, col) +
            flood(grid, row, col + 1) +
            flood(grid, row, col - 1)
        );
    }
}

