// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[][] grid = matrix(data, "heights");
        int rows = grid.length,
            cols = rows == 0 ? 0 : grid[0].length;
        if (rows == 0 || cols == 0) return new int[0][];
        boolean[][] pacific = new boolean[rows][cols],
            atlantic = new boolean[rows][cols];
        class Search {

            void visit(int row, int col, boolean[][] visited) {
                if (visited[row][col]) return;
                visited[row][col] = true;
                trace("grid", grid, "row", row, "col", col, "visited", visited);
                for (int[] delta : DIRECTIONS) {
                    int r = row + delta[0],
                        c = col + delta[1];
                    if (
                        r >= 0 &&
                        c >= 0 &&
                        r < rows &&
                        c < cols &&
                        grid[r][c] >= grid[row][col]
                    ) visit(r, c, visited);
                }
            }
        }
        Search search = new Search();
        for (int r = 0; r < rows; r++) {
            search.visit(r, 0, pacific);
            search.visit(r, cols - 1, atlantic);
        }
        for (int c = 0; c < cols; c++) {
            search.visit(0, c, pacific);
            search.visit(rows - 1, c, atlantic);
        }
        List<int[]> result = new ArrayList<>();
        for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++) if (
            pacific[r][c] && atlantic[r][c]
        ) result.add(new int[] { r, c });
        return result;
    }

    static final int[][] DIRECTIONS = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
}

