import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int n = num(data, "numCourses");
        int[][] edges = matrix(data, "prerequisites");
        for (int[] e : edges) {
            int a = e[0];
            e[0] = e[1];
            e[1] = a;
        }
        return topological(n, edges, 0).size() == n;
    }

    static List<Integer> topological(int n, int[][] edges, int start) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n + start; i++) graph.add(new ArrayList<>());
        int[] indegree = new int[n + start];
        for (int[] e : edges) {
            graph.get(e[0]).add(e[1]);
            indegree[e[1]]++;
        }
        Deque<Integer> queue = new ArrayDeque<>();
        for (int i = start; i < n + start; i++) if (indegree[i] == 0) queue.add(i);
        List<Integer> order = new ArrayList<>();
        while (!queue.isEmpty()) {
            int current = queue.remove();
            order.add(current);
            for (int neighbor : graph.get(current))
                if (--indegree[neighbor] == 0) queue.add(neighbor);
            trace(
                "graph",
                graph,
                "indegree",
                indegree,
                "queue",
                queue,
                "current",
                current,
                "order",
                order
            );
        }
        return order.size() == n ? order : new ArrayList<>();
    }
}

