import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String[] words = strings(data, "words");
        Map<Character, Set<Character>> graph = new TreeMap<>();
        Map<Character, Integer> indegree = new TreeMap<>();
        for (String word : words)
            for (char c : word.toCharArray()) {
                graph.putIfAbsent(c, new TreeSet<>());
                indegree.put(c, 0);
            }
        for (int i = 1; i < words.length; i++) {
            String a = words[i - 1],
                b = words[i];
            if (a.length() > b.length() && a.startsWith(b)) return "";
            for (int j = 0; j < Math.min(a.length(), b.length()); j++) if (
                a.charAt(j) != b.charAt(j)
            ) {
                char from = a.charAt(j),
                    to = b.charAt(j);
                if (graph.get(from).add(to)) indegree.put(to, indegree.get(to) + 1);
                break;
            }
        }
        Deque<Character> queue = new ArrayDeque<>();
        for (char c : indegree.keySet()) if (indegree.get(c) == 0) queue.add(c);
        String result = "";
        while (!queue.isEmpty()) {
            char current = queue.remove();
            result += current;
            for (char neighbor : graph.get(current)) {
                indegree.put(neighbor, indegree.get(neighbor) - 1);
                if (indegree.get(neighbor) == 0) queue.add(neighbor);
            }
            trace("graph", graph, "current", current, "result", result, "queue", queue);
        }
        return result.length() == indegree.size() ? result : "";
    }
}

