import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int n = num(data, "n");
        int[][] edges = matrix(data, "edges");
        UnionFind uf = new UnionFind(n);
        int components = n;
        for (int[] e : edges) {
            if (uf.union(e[0], e[1])) components--;
            trace("edges", edges, "parent", uf.parent, "components", components);
        }
        return components;
    }

    static class UnionFind {

        int[] parent;

        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            parent[b] = a;
            return true;
        }
    }
}

