// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[][] edges = matrix(data, "edges");
        int n = 0;
        for (int[] e : edges) n = Math.max(n, Math.max(e[0], e[1]));
        UnionFind uf = new UnionFind(n + 1);
        for (int[] e : edges) {
            trace("edges", edges, "parent", uf.parent, "a", e[0], "b", e[1]);
            if (!uf.union(e[0], e[1])) return e;
        }
        return new int[0];
    }

    static class UnionFind {

        int[] parent;

        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            parent[b] = a;
            return true;
        }
    }
}

