import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        List<Object> accounts = list(data.get("accounts"));
        UnionFind uf = new UnionFind(accounts.size());
        Map<String, Integer> owners = new TreeMap<>();
        for (int i = 0; i < accounts.size(); i++) {
            List<Object> account = list(accounts.get(i));
            for (int j = 1; j < account.size(); j++) {
                String email = (String) account.get(j);
                if (owners.containsKey(email)) uf.union(i, owners.get(email));
                owners.put(email, i);
                trace("parent", uf.parent, "current", i, "accounts", accounts);
            }
        }
        Map<Integer, List<String>> groups = new TreeMap<>();
        for (Map.Entry<String, Integer> entry : owners.entrySet())
            groups
                .computeIfAbsent(uf.find(entry.getValue()), k -> new ArrayList<>())
                .add(entry.getKey());
        List<List<String>> result = new ArrayList<>();
        for (Map.Entry<Integer, List<String>> entry : groups.entrySet()) {
            List<String> account = new ArrayList<>();
            account.add((String) list(accounts.get(entry.getKey())).get(0));
            account.addAll(entry.getValue());
            result.add(account);
        }
        result.sort(Comparator.comparing(a -> String.join("", a)));
        return result;
    }

    static class UnionFind {

        int[] parent;

        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            parent[b] = a;
            return true;
        }
    }
}

