public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int rows = num(data, "m"),
            cols = num(data, "n");
        int[][] grid = new int[rows][cols];
        UnionFind uf = new UnionFind(rows * cols);
        boolean[] land = new boolean[rows * cols];
        int count = 0;
        List<Integer> result = new ArrayList<>();
        for (int[] p : matrix(data, "positions")) {
            int row = p[0],
                col = p[1],
                id = row * cols + col;
            if (!land[id]) {
                land[id] = true;
                grid[row][col] = 1;
                count++;
                for (int[] delta : DIRECTIONS) {
                    int r = row + delta[0],
                        c = col + delta[1];
                    if (
                        r >= 0 &&
                        c >= 0 &&
                        r < rows &&
                        c < cols &&
                        land[r * cols + c] &&
                        uf.union(id, r * cols + c)
                    ) count--;
                }
            }
            result.add(count);
            trace(
                "grid",
                grid,
                "parent",
                uf.parent,
                "row",
                row,
                "col",
                col,
                "count",
                count
            );
        }
        return result;
    }

    static final int[][] DIRECTIONS = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };

    static class UnionFind {

        int[] parent;

        UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
