import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int n = num(data, "n"),
            k = num(data, "k");
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) graph.add(new ArrayList<>());
        for (int[] e : matrix(data, "times"))
            graph.get(e[0]).add(new int[] { e[1], e[2] });
        long[] distance = new long[n + 1];
        Arrays.fill(distance, Long.MAX_VALUE / 4);
        PriorityQueue<long[]> heap = new PriorityQueue<>(
            Comparator.comparingLong(a -> a[0])
        );
        distance[k] = 0;
        heap.add(new long[] { 0, k });
        while (!heap.isEmpty()) {
            long[] entry = heap.remove();
            long cost = entry[0];
            int current = (int) entry[1];
            if (cost != distance[current]) continue;
            for (int[] e : graph.get(current))
                if (cost + e[1] < distance[e[0]]) {
                    distance[e[0]] = cost + e[1];
                    heap.add(new long[] { distance[e[0]], e[0] });
                }
            trace(
                "graph",
                graph,
                "distance",
                distance,
                "current",
                current,
                "cost",
                cost,
                "heap",
                heap
            );
        }
        long best = 0;
        for (int i = 1; i <= n; i++) best = Math.max(best, distance[i]);
        return best == Long.MAX_VALUE / 4 ? -1 : best;
    }
}

