import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int n = num(data, "n"),
            start = num(data, "start"),
            end = num(data, "end");
        List<List<double[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        int[][] edges = matrix(data, "edges");
        List<Object> probabilities = list(data.get("succProb"));
        for (int i = 0; i < edges.length; i++) {
            int a = edges[i][0],
                b = edges[i][1];
            double p = ((Number) probabilities.get(i)).doubleValue();
            graph.get(a).add(new double[] { b, p });
            graph.get(b).add(new double[] { a, p });
        }
        double[] distance = new double[n];
        PriorityQueue<double[]> heap = new PriorityQueue<>((a, b) ->
            Double.compare(b[0], a[0])
        );
        distance[start] = 1;
        heap.add(new double[] { 1, start });
        while (!heap.isEmpty()) {
            double[] entry = heap.remove();
            double probability = entry[0];
            int current = (int) entry[1];
            trace(
                "graph",
                graph,
                "distance",
                distance,
                "current",
                current,
                "probability",
                probability,
                "heap",
                heap
            );
            if (current == end) return probability;
            if (probability < distance[current]) continue;
            for (double[] e : graph.get(current)) {
                int neighbor = (int) e[0];
                if (probability * e[1] > distance[neighbor]) {
                    distance[neighbor] = probability * e[1];
                    heap.add(new double[] { distance[neighbor], neighbor });
                }
            }
        }
        return 0;
    }
}

