import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int n = num(data, "n"),
            src = num(data, "src"),
            dst = num(data, "dst"),
            k = num(data, "k");
        int[][] flights = matrix(data, "flights");
        long[] distance = new long[n];
        long infinity = Long.MAX_VALUE / 4;
        Arrays.fill(distance, infinity);
        distance[src] = 0;
        for (int round = 0; round <= k; round++) {
            long[] next = distance.clone();
            for (int[] e : flights)
                if (distance[e[0]] != infinity) next[e[1]] = Math.min(
                    next[e[1]],
                    distance[e[0]] + e[2]
                );
            distance = next;
            trace("edges", flights, "distance", distance, "round", round);
        }
        return distance[dst] == infinity ? -1 : distance[dst];
    }
}

