import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[][] grid = matrix(data, "grid");
        int rows = grid.length,
            cols = grid[0].length;
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) Arrays.fill(row, Integer.MAX_VALUE);
        PriorityQueue<int[]> heap = new PriorityQueue<>(
            Comparator.comparingInt(a -> a[0])
        );
        distance[0][0] = grid[0][0];
        heap.add(new int[] { grid[0][0], 0, 0 });
        while (!heap.isEmpty()) {
            int[] entry = heap.remove();
            int cost = entry[0],
                row = entry[1],
                col = entry[2];
            trace(
                "grid",
                grid,
                "dp",
                distance,
                "row",
                row,
                "col",
                col,
                "cost",
                cost,
                "heap",
                heap
            );
            if (row == rows - 1 && col == cols - 1) return cost;
            if (cost != distance[row][col]) continue;
            for (int[] delta : DIRECTIONS) {
                int r = row + delta[0],
                    c = col + delta[1];
                if (r >= 0 && c >= 0 && r < rows && c < cols) {
                    int next = Math.max(cost, grid[r][c]);
                    if (next < distance[r][c]) {
                        distance[r][c] = next;
                        heap.add(new int[] { next, r, c });
                    }
                }
            }
        }
        return -1;
    }

    static final int[][] DIRECTIONS = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
}

