import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        Map<String, Integer> counts = new HashMap<>();
        for (String task : strings(data, "tasks"))
            counts.put(task, counts.getOrDefault(task, 0) + 1);
        PriorityQueue<Integer> heap = new PriorityQueue<>(Comparator.reverseOrder());
        heap.addAll(counts.values());
        Deque<int[]> queue = new ArrayDeque<>();
        int time = 0,
            n = num(data, "n");
        while (!heap.isEmpty() || !queue.isEmpty()) {
            time++;
            if (!heap.isEmpty()) {
                int remaining = heap.remove() - 1;
                if (remaining > 0) queue.add(new int[] { time + n, remaining });
            }
            if (!queue.isEmpty() && queue.peek()[0] <= time) heap.add(queue.remove()[1]);
            trace("heap", heap, "queue", queue, "time", time);
        }
        return time;
    }
}

