import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        PriorityQueue<Integer> lower = new PriorityQueue<>(Comparator.reverseOrder()),
            upper = new PriorityQueue<>();
        List<Double> result = new ArrayList<>();
        for (int value : ints(data, "nums")) {
            lower.add(value);
            upper.add(lower.remove());
            if (upper.size() > lower.size()) lower.add(upper.remove());
            double median =
                lower.size() > upper.size()
                    ? lower.peek()
                    : ((double) lower.peek() + upper.peek()) / 2;
            result.add(median);
            trace("lower", lower, "upper", upper, "median", median, "result", result);
        }
        return result;
    }
}

