import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] candidates = Arrays.stream(ints(data, "candidates"))
            .distinct()
            .sorted()
            .toArray();
        List<Integer> path = new ArrayList<>();
        List<List<Integer>> result = new ArrayList<>();
        class Search {

            void visit(int start, int remaining) {
                trace("path", path, "remaining", remaining, "result", result);
                if (remaining == 0) {
                    result.add(new ArrayList<>(path));
                    return;
                }
                for (
                    int i = start;
                    i < candidates.length && candidates[i] <= remaining;
                    i++
                ) {
                    path.add(candidates[i]);
                    visit(i, remaining - candidates[i]);
                    path.remove(path.size() - 1);
                }
            }
        }
        new Search().visit(0, num(data, "target"));
        return result;
    }
}

