        String digits = str(data, "digits");
        String[] letters = {
            "",
            "",
            "abc",
            "def",
            "ghi",
            "jkl",
            "mno",
            "pqrs",
            "tuv",
            "wxyz",
        };
        List<String> result = new ArrayList<>();
        class Search {

            void visit(int i, String path) {
                trace("path", path, "digits", digits, "i", i, "result", result);
                if (i == digits.length()) {
                    result.add(path);
                    return;
                }
                for (char c : letters[digits.charAt(i) - '0'].toCharArray())
                    visit(i + 1, path + c);
            }
        }
        if (!digits.isEmpty()) new Search().visit(0, "");
        return result;
    }
}

