import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int n = num(data, "n");
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        Set<Integer> columns = new HashSet<>(),
            diagonal = new HashSet<>(),
            antidiagonal = new HashSet<>();
        List<List<String>> result = new ArrayList<>();
        class Search {

            void visit(int row) {
                if (row == n) {
                    List<String> answer = new ArrayList<>();
                    for (char[] line : board) answer.add(new String(line));
                    result.add(answer);
                    return;
                }
                for (int col = 0; col < n; col++) {
                    if (
                        columns.contains(col) ||
                        diagonal.contains(row - col) ||
                        antidiagonal.contains(row + col)
                    ) continue;
                    board[row][col] = 'Q';
                    columns.add(col);
                    diagonal.add(row - col);
                    antidiagonal.add(row + col);
                    trace("board", board, "row", row, "col", col, "result", result);
                    visit(row + 1);
                    board[row][col] = '.';
                    columns.remove(col);
                    diagonal.remove(row - col);
                    antidiagonal.remove(row + col);
                }
            }
        }
        new Search().visit(0);
        return result;
    }
}

