public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s");
        boolean[][] dp = new boolean[s.length()][s.length()];
        int count = 0;
        for (int left = s.length() - 1; left >= 0; left--) for (
            int right = left;
            right < s.length();
            right++
        ) {
            dp[left][right] =
                s.charAt(left) == s.charAt(right) &&
                (right - left < 2 || dp[left + 1][right - 1]);
            if (dp[left][right]) count++;
            trace("s", s, "dp", dp, "left", left, "right", right, "count", count);
        }
        return count;
    }
}

