import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s");
        if (s.isEmpty()) return 0;
        long[] dp = new long[s.length() + 1];
        dp[0] = 1;
        for (int i = 1; i <= s.length(); i++) {
            if (s.charAt(i - 1) != '0') dp[i] += dp[i - 1];
            if (i >= 2) {
                int pair = Integer.parseInt(s.substring(i - 2, i));
                if (pair >= 10 && pair <= 26) dp[i] += dp[i - 2];
            }
            trace("s", s, "dp", dp, "i", i);
        }
        return dp[s.length()];
    }
}

