import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] input = ints(data, "nums"),
            nums = new int[input.length + 2];
        nums[0] = nums[nums.length - 1] = 1;
        System.arraycopy(input, 0, nums, 1, input.length);
        int n = nums.length;
        long[][] dp = new long[n][n];
        for (int width = 2; width < n; width++) for (
            int left = 0;
            left + width < n;
            left++
        ) {
            int right = left + width;
            for (int k = left + 1; k < right; k++) {
                dp[left][right] = Math.max(
                    dp[left][right],
                    dp[left][k] + (long) nums[left] * nums[k] * nums[right] + dp[k][right]
                );
                trace("nums", nums, "dp", dp, "left", left, "right", right, "k", k);
            }
        }
        return dp[0][n - 1];
    }
}

