public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int amount = num(data, "amount");
        int[] coins = ints(data, "coins"),
            dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;
        for (int i = 1; i <= amount; i++) {
            for (int coin : coins)
                if (coin > 0 && coin <= i) dp[i] = Math.min(dp[i], 1 + dp[i - coin]);
            trace("dp", dp, "i", i, "coins", coins);
        }
        return dp[amount] > amount ? -1 : dp[amount];
    }
}

