// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        Map<Integer, Long> dp = new TreeMap<>();
        dp.put(0, 1L);
        for (int value : ints(data, "nums")) {
            Map<Integer, Long> next = new TreeMap<>();
            for (Map.Entry<Integer, Long> entry : dp.entrySet()) {
                int total = entry.getKey();
                long count = entry.getValue();
                next.put(total + value, next.getOrDefault(total + value, 0L) + count);
                next.put(total - value, next.getOrDefault(total - value, 0L) + count);
            }
            dp = next;
            trace("dp", dp, "value", value);
        }
        return dp.getOrDefault(num(data, "target"), 0L);
    }
}

