// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        long hold = Long.MIN_VALUE / 4,
            sold = Long.MIN_VALUE / 4,
            rest = 0;
        List<long[]> dp = new ArrayList<>();
        for (int price : ints(data, "prices")) {
            long nextHold = Math.max(hold, rest - price),
                nextSold = hold + price,
                nextRest = Math.max(rest, sold);
            hold = nextHold;
            sold = nextSold;
            rest = nextRest;
            dp.add(new long[] { hold, sold, rest });
            trace("dp", dp, "hold", hold, "sold", sold, "rest", rest, "price", price);
        }
        return Math.max(rest, sold);
    }
}

