import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s"),
            p = str(data, "p");
        boolean[][] dp = new boolean[s.length() + 1][p.length() + 1];
        dp[0][0] = true;
        for (int j = 2; j <= p.length(); j++) if (p.charAt(j - 1) == '*') dp[0][j] =
            dp[0][j - 2];
        for (int i = 1; i <= s.length(); i++) for (int j = 1; j <= p.length(); j++) {
            if (p.charAt(j - 1) == '*' && j >= 2) dp[i][j] =
                dp[i][j - 2] ||
                ((p.charAt(j - 2) == '.' || p.charAt(j - 2) == s.charAt(i - 1)) &&
                    dp[i - 1][j]);
            else if (p.charAt(j - 1) == '.' || p.charAt(j - 1) == s.charAt(i - 1)) dp[i][
                j
            ] = dp[i - 1][j - 1];
            trace("dp", dp, "s", s, "p", p, "i", i, "j", j);
        }
        return dp[s.length()][p.length()];
    }
}

