import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] gas = ints(data, "gas"),
            cost = ints(data, "cost");
        long total = 0,
            tank = 0;
        int start = 0;
        for (int i = 0; i < gas.length; i++) {
            long delta = (long) gas[i] - cost[i];
            total += delta;
            tank += delta;
            if (tank < 0) {
                tank = 0;
                start = i + 1;
            }
            trace("gas", gas, "cost", cost, "i", i, "tank", tank, "start", start);
        }
        return total >= 0 && gas.length > 0 ? start : -1;
    }
}

