public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        int[] ratings = ints(data, "ratings"),
            candies = new int[ratings.length];
        Arrays.fill(candies, 1);
        for (int i = 1; i < ratings.length; i++) {
            if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
            trace("ratings", ratings, "candies", candies, "i", i);
        }
        for (int i = ratings.length - 2; i >= 0; i--) {
            if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(
                candies[i],
                candies[i + 1] + 1
            );
            trace("ratings", ratings, "candies", candies, "i", i);
        }
        long total = 0;
        for (int candy : candies) total += candy;
        return total;
    }
}

