import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String haystack = str(data, "haystack"),
            needle = str(data, "needle");
        if (needle.isEmpty()) return 0;
        int[] lps = prefix(needle);
        int j = 0;
        for (int i = 0; i < haystack.length(); i++) {
            while (j > 0 && haystack.charAt(i) != needle.charAt(j)) j = lps[j - 1];
            if (haystack.charAt(i) == needle.charAt(j)) j++;
            trace("haystack", haystack, "needle", needle, "lps", lps, "i", i, "j", j);
            if (j == needle.length()) return i - j + 1;
        }
        return -1;
    }

    static int[] prefix(String s) {
        int[] lps = new int[s.length()];
        int j = 0;
        for (int i = 1; i < s.length(); i++) {
            while (j > 0 && s.charAt(i) != s.charAt(j)) j = lps[j - 1];
            if (s.charAt(i) == s.charAt(j)) j++;
            lps[i] = j;
            trace("s", s, "lps", lps, "i", i, "j", j);
        }
        return lps;
    }
}

