import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s");
        Set<Integer> seen = new HashSet<>(),
            repeated = new HashSet<>();
        List<String> result = new ArrayList<>();
        int rolling = 0;
        for (int i = 0; i < s.length(); i++) {
            rolling = ((rolling << 2) | "ACGT".indexOf(s.charAt(i))) & ((1 << 20) - 1);
            if (i >= 9) {
                if (seen.contains(rolling) && repeated.add(rolling)) result.add(
                    s.substring(i - 9, i + 1)
                );
                seen.add(rolling);
            }
            trace("s", s, "i", i, "rolling", rolling, "result", result);
        }
        return result;
    }
}

