import java.util.*;

// Input helpers and trace(name, value, ...) are provided by Trace.
public class Solution extends Trace {

    public Object solve(Map<String, Object> data) {
        String s = str(data, "s");
        int n = s.length();
        int[] sequence = new int[2 * n + 1];
        for (int i = 0; i < n; i++) {
            sequence[i] = s.charAt(i);
            sequence[2 * n - i] = s.charAt(i);
        }
        sequence[n] = -1;
        int[] lps = new int[sequence.length];
        int j = 0;
        for (int i = 1; i < sequence.length; i++) {
            while (j > 0 && sequence[i] != sequence[j]) j = lps[j - 1];
            if (sequence[i] == sequence[j]) j++;
            lps[i] = j;
            trace("s", s, "sequence", sequence, "lps", lps, "i", i, "j", j);
        }
        return (
            new StringBuilder(s.substring(lps[lps.length - 1])).reverse().toString() + s
        );
    }
}
